consumer_audit.reproduction_audit_script:
const fs = require('node:fs');
const cp = require('node:child_process');
const path = require('node:path');
const root = process.cwd();
const ts = require(path.join(root, 'node_modules/typescript'));
const pkg = JSON.parse(cp.execFileSync('git', ['show', 'origin/dev:package.json'], {encoding:'utf8'}));
const deps = {...pkg.dependencies, ...pkg.devDependencies};
const rows = Object.fromEntries(Object.entries(deps).map(([name, declared]) => [name, {name, declared, consumers: []}]));
const unresolved = [];
const files = cp.execFileSync('git', ['ls-files','-z'], {encoding:'utf8'}).split('\0').filter(Boolean);
function record(spec, file, node, sf, kind) {
  const name = Object.keys(rows).find(n => spec === n || spec.startsWith(n+'/'));
  if(name) rows[name].consumers.push({file, line:sf.getLineAndCharacterOfPosition(node.getStart(sf)).line+1, kind, specifier:spec});
}
for(const file of files.filter(f => /\.(?:[cm]?[jt]sx?|css)$/.test(f))) {
  const source=fs.readFileSync(file,'utf8');
  const sf=ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true);
  function visit(node) {
    if((ts.isImportDeclaration(node)||ts.isExportDeclaration(node)) && node.moduleSpecifier && ts.isStringLiteralLike(node.moduleSpecifier)) {
      const typeOnly = node.importClause?.isTypeOnly || node.isTypeOnly || (node.importClause?.namedBindings?.elements?.length && !node.importClause.name && node.importClause.namedBindings.elements.every(e=>e.isTypeOnly));
      record(node.moduleSpecifier.text,file,node,sf,typeOnly?'type import':'static import/export');
    }
    if(ts.isCallExpression(node) && (node.expression.kind===ts.SyntaxKind.ImportKeyword || node.expression.getText(sf)==='require' || node.expression.getText(sf)==='require.resolve')) {
      const arg=node.arguments[0];
      if(arg && ts.isStringLiteralLike(arg)) record(arg.text,file,node,sf,node.expression.kind===ts.SyntaxKind.ImportKeyword?'dynamic import':'require');
      else unresolved.push({file,line:sf.getLineAndCharacterOfPosition(node.getStart(sf)).line+1,expression:node.getText(sf)});
    }
    ts.forEachChild(node,visit);
  }
  visit(sf);
}
fs.writeFileSync('/tmp/fe-dep-audit.json', JSON.stringify({scannedFiles:files.length,packages:Object.values(rows),unresolved},null,2)+'\n');
for(const row of Object.values(rows)) console.log(row.name+': '+row.consumers.length+' '+row.consumers.slice(0,2).map(c=>c.file+':'+c.line+' ('+c.kind+')').join(', '));
console.log('NONLITERAL',JSON.stringify(unresolved));
